            display_val = round_float(attr_val) if isinstance(attr_val, float) else attr_val

            matched.append({
                "id": wi.id,
                "name": wi.name,
                "state": wi.state.name if hasattr(wi.state, 'name') else str(wi.state),
                "attribute_value": display_val,
            })

